#!/usr/bin/env python3
"""Extract first ~500 chars of text from each file in papers/all for classification."""
import os
import json

DIR = "/root/papers/all"

def extract_pdf_text(filepath, max_chars=800):
    """Extract text from PDF using pdftotext (first 2 pages)."""
    import subprocess
    try:
        result = subprocess.run(
            ["pdftotext", "-l", "2", filepath, "-"],
            capture_output=True, text=True, timeout=30
        )
        text = result.stdout.strip()
        return text[:max_chars] if text else ""
    except Exception as e:
        return f"ERROR: {e}"

def extract_docx_text(filepath, max_chars=800):
    """Extract text from DOCX."""
    from docx import Document
    try:
        doc = Document(filepath)
        text = "\n".join([p.text for p in doc.paragraphs])
        return text[:max_chars] if text else ""
    except Exception as e:
        return f"ERROR: {e}"

def extract_pptx_text(filepath, max_chars=800):
    """Extract text from PPTX."""
    from pptx import Presentation
    try:
        prs = Presentation(filepath)
        texts = []
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, "text"):
                    texts.append(shape.text)
        text = "\n".join(texts)
        return text[:max_chars] if text else ""
    except Exception as e:
        return f"ERROR: {e}"

results = {}
files = sorted(os.listdir(DIR))
for f in files:
    filepath = os.path.join(DIR, f)
    if not os.path.isfile(filepath):
        continue
    ext = f.lower().rsplit(".", 1)[-1] if "." in f else ""
    if ext == "pdf":
        text = extract_pdf_text(filepath)
    elif ext == "docx":
        text = extract_docx_text(filepath)
    elif ext == "pptx":
        text = extract_pptx_text(filepath)
    else:
        text = f"UNKNOWN FORMAT: {ext}"
    results[f] = text

# Output as JSON
with open("/root/file_texts.json", "w") as out:
    json.dump(results, out, indent=2)

print(f"Extracted text from {len(results)} files")

